export interface TwgLookup {
  env?: NodeJS.ProcessEnv;
  platform?: string;
  homedir?: string;
  exists?: (candidate: string) => boolean;
}

const isFile = (candidate: string) => statSync(candidate, { throwIfNoEntry: false })?.isFile() === true;

